code.cpp:
class Solution {
public:
    int dominantIndex(vector<int>& nums) {
        int maxIndex = 0;
        int maxVal = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            if (nums[i] > maxVal) {
                maxVal = nums[i];
                maxIndex = i;
            }
        }
        for (int i = 0; i < (int)nums.size(); i++) {
            if (i != maxIndex && maxVal < 2 * nums[i]) {
                return -1;
            }
        }
        return maxIndex;
    }
};
